(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.InverseLesson,num=window.LinearLesson;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function draw(){const direction=$('[name="direction"]:checked').value,x=Number($('#inverse-input').value),q=num.rational(x),forward=direction==='forward',middle=num.rational(forward?2*x:x-1),result=forward?core.forward(q):core.inverse(q),recovered=forward?core.inverse(result):core.forward(result);$('#inverse-output').value=x;math($('#stage-input'),String(x));math($('#stage-middle'),num.fractionTex(middle));math($('#stage-final'),num.fractionTex(result));$('#middle-label').textContent=forward?'Tahap 1 · kalikan dua':'Tahap 1 · kurangi satu';$('#final-label').textContent=forward?'Tahap 2 · tambah satu':'Tahap 2 · bagi dua';math($('#inverse-equation'),forward?`f(${x})=2\\times(${x})+1=${num.fractionTex(result)}`:`f^{-1}(${x})=\\frac{(${x})-1}{2}=${num.fractionTex(result)}`);$('#roundtrip-feedback').innerHTML=`Jika hasil ini dimasukkan ke ${forward?'fungsi invers':'fungsi semula'}, kita memperoleh <span data-tex="${num.fractionTex(recovered)}"></span> kembali: <span data-tex="${forward?'f^{-1}':'f'}\\left(${num.fractionTex(result)}\\right)=${num.fractionTex(recovered)}"></span>.`;}
document.querySelectorAll('[name="direction"]').forEach(e=>e.addEventListener('change',draw));$('#inverse-input').addEventListener('input',draw);$('#reset-inverse').addEventListener('click',()=>{$('[name="direction"][value="forward"]').checked=true;$('#inverse-input').value=2;draw();});draw();
function branch(){const y=Number($('#square-output').value),which=$('[name="branch"]:checked').value,values=core.preimages(y,which);$('#square-output-value').value=y;math($('#preimage-equation'),`x^2=${y}`);$('#preimage-cards').replaceChildren();values.forEach(v=>{const card=document.createElement('div'),label=document.createElement('p'),equation=document.createElement('div');label.textContent='Calon masukan lama';const root=Number.isInteger(Math.sqrt(y))?String(Math.sqrt(y)):`\\sqrt{${y}}`,tex=v<0?'-'+root:root;math(equation,`x=${tex}`);card.append(label,equation);$('#preimage-cards').append(card);});let message;if(y<0)message='Tidak ada masukan real yang kuadratnya negatif. Nilai ini di luar range kuadrat dan tidak boleh menjadi masukan fungsi invers pada cabang mana pun.';else if(which==='all')message=y===0?'Keluaran nol hanya memiliki satu calon masukan. Namun kuadrat pada seluruh bilangan real tetap tidak memiliki fungsi invers, karena keluaran positif mempunyai dua calon masukan.':'Ada dua calon masukan berbeda. Jika keduanya diperbolehkan, proses balik tidak memberikan tepat satu keluaran. Kuadrat pada seluruh bilangan real tidak memiliki fungsi invers.';else message=which==='positive'?'Ada satu calon masukan pada domain tidak negatif. Cabang ini memiliki fungsi invers akar kuadrat utama, dengan domain bilangan tidak negatif.':'Ada satu calon masukan pada domain tidak positif. Cabang ini memiliki fungsi invers negatif akar kuadrat, dengan domain bilangan tidak negatif.';$('#branch-feedback').textContent=message;}
document.querySelectorAll('[name="branch"]').forEach(e=>e.addEventListener('change',branch));$('#square-output').addEventListener('input',branch);branch();
const questions=[{tex:'f(x)=2x+1',prompt:'Berapa nilai invers fungsi ini pada masukan tujuh?',n:3,d:1,hint:'Kurangi tujuh dengan satu, lalu bagi dua.',why:'Tujuh dikurangi satu menjadi enam, lalu dibagi dua menjadi tiga. Ini nilai fungsi invers, bukan satu dibagi keluaran fungsi semula.'},{tex:'f(x)=2x+1',prompt:'Berapa nilai invers fungsi ini pada masukan dua?',n:1,d:2,hint:'Masukan invers tidak harus berasal dari penggeser. Kurangi satu, lalu bagi dua.',why:'Dua dikurangi satu lalu dibagi dua menghasilkan setengah. Keluaran fungsi semula untuk masukan setengah memang dua.'},{tex:'u(x)=3x-2',prompt:'Dengan domain dan kodomain bilangan real, berapa nilai invers fungsi ini pada masukan empat?',n:2,d:1,hint:'Tambahkan dua untuk membatalkan pengurangan, lalu bagi tiga.',why:'Empat ditambah dua menjadi enam, kemudian dibagi tiga menjadi dua. Fungsi semula mengubah dua menjadi empat.'}];const solved=new Set();function report(i,ok,message){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=message;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n,q.d));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis satu bilangan, misalnya 3 atau 1/2.':'Belum tepat. Batalkan operasi dalam urutan terbalik, lalu periksa dengan fungsi semula.');}));
const choices=[{tex:'h(x)=x^2,\\quad D=\\mathbb R',prompt:'Mengapa fungsi ini tidak memiliki fungsi invers dari range-nya ke domain semula?',options:['Ada dua masukan berbeda yang menghasilkan keluaran sama.','Karena kuadrat tidak menerima masukan negatif.','Karena semua fungsi harus linear agar bisa dibalik.'],answer:0,why:'Dua dan negatif dua sama-sama menghasilkan empat. Proses balik tidak dapat memilih satu masukan secara pasti.'},{tex:'h:(-\\infty,0]\\to[0,\\infty),\\quad h(x)=x^2',prompt:'Pada cabang ini, berapa nilai invers untuk masukan sembilan?',options:['Tiga.','Negatif tiga.','Tiga dan negatif tiga sekaligus.'],answer:1,why:'Domain fungsi semula hanya memuat masukan tidak positif. Maka masukan lama yang menghasilkan sembilan adalah negatif tiga.'},{tex:'h:[0,\\infty)\\to[0,\\infty),\\quad h(x)=x^2',prompt:'Apa domain fungsi invers pada cabang ini?',options:['Semua bilangan real.','Hanya bilangan real positif, tanpa nol.','Semua bilangan real tidak negatif, termasuk nol.'],answer:2,why:'Domain invers adalah range fungsi semula. Kuadrat pada cabang ini mencapai nol dan semua bilangan positif, sehingga nol ikut diperbolehkan.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}">${o}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-inverse-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-inverse-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();